        $dataArray = json_decode($data, true);

        $tipoMapping = [
            'ATROPELLO' => 7,
            'CAIDA DE OCUPANTE' => 8,
            'CHOQUE' => 2,
            'CHOQUE CON OBJETO FIJO' => 3,
            'N/A' => 1,
            'OTRO' => 9,
            'SALIDA DE CALZADA' => 6,
            'VOLCAMIENTO' => 5,
            'VOLCAMIENTO LATERAL' => 4,
        ];

        foreach ($dataArray['array'] as $dataItem) {
            $tipoNumber = $tipoMapping[$dataItem['TIPO']] ?? null;

            if ($tipoNumber === null) {
                $tipoNumber = 1;
            }

            $coordinates = explode(', ', $dataItem['COORDENADAS']);
            $latitude = $coordinates[0] ?? null;
            $longitude = $coordinates[1] ?? null;

            $uuid = Str::uuid();
            DB::table('data_ditra')->insert([
                'year' => $dataItem['ANIO '],
                'uuid' => $uuid,
                'occurrence_date' => $dataItem['FECHA_OCURRENCIA'],
                'month' => $dataItem['MES '],
                'day' => $dataItem['DIA'],
                'hour' => $dataItem['HORA'],
                'hour_range' => $dataItem['RANGO_HORA'],
                'sectional' => $dataItem['SECCIONAL'],
                'latitude' => $latitude,
                'longitude' => $longitude,
                'assigned' => $dataItem['ADSCRITO'],
                'identification' => $dataItem['IDENTIFICACION'],
                'grade' => $dataItem['GRADO'],
                'names' => $dataItem['NOMBRES'],
                'last_names' => $dataItem['APELLIDOS'],
                'age' => $dataItem['EDAD'],
                'age_range' => $dataItem['RANGO DE EDAD '],
                'gender' => $dataItem['GENERO'],
                'marital_status' => $dataItem['ESTADO CIVIL'],
                'intoxication' => $dataItem['EMBRIAGUEZ'],
                'responsibility' => $dataItem['RESPONSABILIDAD'],
                'plate' => $dataItem['PLACA'],
                'vehicle_class' => $dataItem['CLASE_V'],
                'model' => $dataItem['MODELO'],
                'cc' => $dataItem['CC'],
